import { provideDirection, useDirection } from "@barqjs/aria/i18n";
import {
  Slider as AriaSlider,
  SliderOutput,
  SliderThumb,
  SliderTrack,
  runsBackwards,
  useSlider,
  type SliderComponentProps,
  type SliderContextValue,
} from "@barqjs/aria/slider";
import type { Accessor, Incoming } from "@barqjs/core";
import { layer } from "@barqjs/css";

import "../theme/layers.ts";
import { box } from "../lib/shared-box.ts";
import { omit } from "../lib/slot.ts";
import { when } from "../lib/shared-when.ts";

const ui = layer("barq.ui");

const root = ui(box.noSelect, {
  position: "relative",
  display: "flex",
  width: "100%",
  touchAction: "none",
  alignItems: "center",
  '[data-orientation="vertical"]': {
    height: "100%",
    minHeight: "calc(var(--spacing) * 40)",
    width: "auto",
    flexDirection: "column",
  },
  "[data-disabled]": {
    opacity: "50%",
  },
});

const track = ui({
  position: "relative",
  flexGrow: "1",
  borderRadius: "calc(infinity * 1px)",
  backgroundColor: "var(--muted)",
  '[data-orientation="horizontal"]': {
    height: "var(--spacing)",
    width: "100%",
  },
  '[data-orientation="vertical"]': {
    height: "100%",
    width: "var(--spacing)",
  },
});

const thumb = ui(box.border, box.transition, box.noSelect, box.forcedColors, when.disabled, {
  position: "absolute",
  display: "block",
  width: "calc(var(--spacing) * 3)",
  height: "calc(var(--spacing) * 3)",
  flexShrink: "0",
  borderRadius: "calc(infinity * 1px)",
  borderColor: "var(--ring)",
  // `bg-white`, not `--background`: the thumb reads as a physical control and
  // stays light in a dark theme, which is what upstream draws.
  backgroundColor: "var(--color-white)",
  "--ui-ring-color": "var(--ring)",
  transitionProperty: "color, box-shadow",
  "@supports (color: color-mix(in lab, red, red))": {
    "--ui-ring-color": "color-mix(in oklab, var(--ring) 50%, transparent)",
  },
  // A 12px thumb is far under the pointer-target minimum, so the press area is
  // grown past the paint, as it is on the switch and the checkbox.
  "::after": {
    content: "var(--ui-content)",
    position: "absolute",
    inset: "calc(var(--spacing) * -2)",
  },
  "@media (hover: hover)": {
    ":hover": {
      "--ui-ring-shadow":
        "var(--ui-ring-inset,) 0 0 0 calc(3px + var(--ui-ring-offset-width)) var(--ui-ring-color, currentcolor)",
      boxShadow:
        "var(--ui-inset-shadow), var(--ui-inset-ring-shadow), var(--ui-ring-offset-shadow), var(--ui-ring-shadow), var(--ui-shadow)",
    },
  },
  ":active": {
    "--ui-ring-shadow":
      "var(--ui-ring-inset,) 0 0 0 calc(3px + var(--ui-ring-offset-width)) var(--ui-ring-color, currentcolor)",
    boxShadow:
      "var(--ui-inset-shadow), var(--ui-inset-ring-shadow), var(--ui-ring-offset-shadow), var(--ui-ring-shadow), var(--ui-shadow)",
  },
  "[data-focus-visible]": {
    "--ui-ring-shadow":
      "var(--ui-ring-inset,) 0 0 0 calc(3px + var(--ui-ring-offset-width)) var(--ui-ring-color, currentcolor)",
    boxShadow:
      "var(--ui-inset-shadow), var(--ui-inset-ring-shadow), var(--ui-ring-offset-shadow), var(--ui-ring-shadow), var(--ui-shadow)",
    "--ui-outline-style": "none",
    outlineStyle: "none",
  },
  ":disabled": {
    pointerEvents: "none",
  },
});

const output = ui({
  position: "absolute",
  width: "1px",
  height: "1px",
  padding: "0",
  margin: "-1px",
  overflow: "hidden",
  clipPath: "inset(50%)",
  whiteSpace: "nowrap",
  borderWidth: "0",
});

/**
 * The filled part of the track, drawn by the track itself.
 *
 * shadcn renders a `<SliderRange>` element for it. There is nothing for such an
 * element to be here — `@barqjs/aria`'s track renders one child per thumb — and
 * it does not need one: the start and end are two custom properties, so
 * dragging writes two numbers and produces no new CSS and no new node.
 *
 * A GRADIENT rather than a pseudo-element, and that is what makes the thumb
 * visible. shadcn clips its `<SliderRange>` to the rounded track with
 * `overflow: hidden`, but the thumb is a child of the track here rather than
 * its sibling, so the same rule cut a 16px thumb down to the track's 6px and
 * left a sliver. A background is clipped by `border-radius` on its own, with
 * the same square ends shadcn's clipped element has, and it clips nothing else.
 */
const range = ui({
  // The fill is the track's own gradient. It carries NO size: `ui(track, range)`
  // merges by property, so a `height: 100%` here won the track's own
  // `height: var(--spacing)` and collapsed the bar to nothing — measured as a
  // 0px track on the slider page. `ALLOWED` records the slot instead.
  '[data-orientation="horizontal"]': {
    backgroundImage:
      "linear-gradient( to right, transparent var(--barq-slider-start), var(--primary) var(--barq-slider-start), var(--primary) var(--barq-slider-end), transparent var(--barq-slider-end) )",
  },
  '[data-orientation="vertical"]': {
    backgroundImage:
      "linear-gradient( to top, transparent var(--barq-slider-start), var(--primary) var(--barq-slider-start), var(--primary) var(--barq-slider-end), transparent var(--barq-slider-end) )",
  },
});

/**
 * Where each thumb sits, keyed off the TRACK's orientation rather than its own.
 *
 * The thumb carries no `data-orientation` — `@barqjs/aria` writes that on the
 * group and on the track — so `&[data-orientation="horizontal"]` matched
 * nothing and every thumb sat at `left: 0` whatever its value. That is invisible
 * to a test asserting on the custom property, and the first thing you see in a
 * browser.
 *
 * The CROSS axis is set here too. shadcn's thumb is a sibling of the track and
 * is centred by the root's `align-items: center`; this one is a child of a
 * 6px-tall track, where the static position is the track's top edge and a 16px
 * thumb hangs 10px below it.
 */
const place = ui({
  '[data-orientation="horizontal"] &': {
    left: "var(--barq-slider-thumb)",
    top: "50%",
    translate: "-50% -50%",
  },
  '[data-orientation="vertical"] &': {
    bottom: "var(--barq-slider-thumb)",
    left: "50%",
    translate: "-50% 50%",
  },
});

export interface SliderProps extends SliderComponentProps {
  /** shadcn's spelling of `minValue`. */
  min?: number;
  /** shadcn's spelling of `maxValue`. */
  max?: number;
  /** shadcn's spelling of `onChange`. */
  onValueChange?: (value: number[]) => void;
  /** shadcn's spelling of `onChangeEnd`. */
  onValueCommit?: (value: number[]) => void;
  /** shadcn's spelling of `isDisabled`. */
  disabled?: boolean;
  /** shadcn's spelling of `isInverted`. */
  inverted?: boolean;
  /** Which end is the minimum, for this slider alone. Defaults to the direction in scope. */
  dir?: "ltr" | "rtl";
}

const UPSTREAM = ["min", "max", "onValueChange", "onValueCommit", "disabled", "inverted"] as const;

/**
 * ```tsx
 * <Slider aria-label="Volume" defaultValue={30} onChange={([v]) => volume.set(v)} />
 * <Slider aria-label="Price" defaultValue={[20, 60]} />
 * ```
 *
 * One value or two: an array makes it a range, and the second thumb is real
 * rather than decorative — each is a visually hidden `<input type="range">`, so
 * the keyboard, the form and a screen reader all talk to the platform.
 */
export function Slider(props: Incoming<SliderProps>) {
  const inherited = useDirection();
  // Declared for the subtree rather than read here, so the pointer and the
  // arrow keys in `@barqjs/aria` mirror with the drawing.
  if (props.dir !== undefined) provideDirection(() => props.dir?.() ?? inherited());

  return (
    <AriaSlider
      {...omit(props, UPSTREAM)}
      data-slot={props["data-slot"]?.() ?? "slider"}
      class={ui(root, props.class?.(), props.className?.())}
      minValue={props.minValue?.() ?? props.min?.()}
      maxValue={props.maxValue?.() ?? props.max?.()}
      isDisabled={props.isDisabled?.() ?? props.disabled?.()}
      isInverted={props.isInverted?.() ?? props.inverted?.()}
      onChange={(value: number[]) => {
        props.onChange?.()?.(value);
        props.onValueChange?.()?.(value);
      }}
      onChangeEnd={(value: number[]) => {
        props.onChangeEnd?.()?.(value);
        props.onValueCommit?.()?.(value);
      }}
    >
      <SliderOutput data-slot="slider-output" class={output} />
      <Fill />
    </AriaSlider>
  );
}

/** The track and its thumbs, reading the state the enclosing slider provides. */
function Fill() {
  const group = useSlider();
  const direction = useDirection();
  const mirrored = (): boolean => isMirrored(group, direction);

  const bounds = (): Record<string, string> => {
    const percents = group.state.values().map((_, index) => group.state.getThumbPercent(index));
    const start = percents.length > 1 ? Math.min(...percents) : 0;
    const end = percents.length > 1 ? Math.max(...percents) : (percents[0] ?? 0);
    return {
      "--barq-slider-start": percent(mirrored() ? 1 - end : start),
      "--barq-slider-end": percent(mirrored() ? 1 - start : end),
    };
  };

  return (
    <SliderTrack data-slot="slider-track" class={ui(track, range)} style={bounds()}>
      {(index: number) => (
        <SliderThumb
          index={index}
          data-slot="slider-thumb"
          data-orientation={orientationOf(group)}
          class={ui(thumb, place)}
          style={at(group, index, mirrored)}
        />
      )}
    </SliderTrack>
  );
}

function orientationOf(group: SliderContextValue): "horizontal" | "vertical" {
  return group.state.orientation();
}

/**
 * Whether the minimum is drawn at the far end of the rules below.
 *
 * Those rules are PHYSICAL on purpose: `left`, `bottom`, `to right`. The
 * pointer arithmetic in `@barqjs/aria` is physical too (a press is measured
 * from the track's left edge) and takes its direction from the scope, not from
 * the element's computed `direction`. Logical properties would follow the
 * computed one, and the two disagree whenever a direction is declared for the
 * widgets without a `dir` attribute above them, leaving a thumb drawn at one
 * end and dragged from the other. Mirroring the numbers keeps one source.
 */
function isMirrored(group: SliderContextValue, direction: Accessor<"ltr" | "rtl">): boolean {
  const backwards = runsBackwards(group.state, direction() === "rtl");
  return group.state.orientation() === "vertical" ? !backwards : backwards;
}

/**
 * A CALL, not the object literal it returns, and that is load-bearing.
 *
 * The compiler proves reactivity rather than guessing it, and
 * `state.getThumbPercent` is an opaque method: written as
 * `style={{ "--x": percent(...) }}` the object is classified static, evaluated
 * once, and the thumb never moves. A call is not something the compiler will
 * evaluate at the call site, so the prop crosses as `() => at(group, index)`
 * and the consumer's effect re-reads it. The track's own `style={bounds()}` is
 * the same shape for the same reason.
 */
function at(
  group: SliderContextValue,
  index: number,
  mirrored: Accessor<boolean>,
): Record<string, string> {
  const along = group.state.getThumbPercent(index);
  return { "--barq-slider-thumb": percent(mirrored() ? 1 - along : along) };
}

/** Two decimal places, because a third of a track is otherwise seventeen digits. */
function percent(fraction: number): string {
  return `${String(Math.round(fraction * 10000) / 100)}%`;
}
